package si.spindl.reports;

import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import si.spindl.identity.TenantAuditEventEntity;
import si.spindl.identity.TenantAuditEventRepository;
import java.math.BigDecimal;
import java.util.*;

@Service
public class WorkflowStudioService {
    public static final String PURCHASE_ORDER_APPROVAL="purchase_order_approval";
    private final TenantWorkflowVersionRepository versions;private final TenantAuditEventRepository audit;
    public WorkflowStudioService(TenantWorkflowVersionRepository versions,TenantAuditEventRepository audit){this.versions=versions;this.audit=audit;}
    @Transactional(readOnly=true) public WorkflowView view(UUID tenantId){var history=versions.findAllByTenantIdAndWorkflowKeyOrderByVersionDesc(tenantId,PURCHASE_ORDER_APPROVAL).stream().map(WorkflowVersionView::from).toList();var published=versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,PURCHASE_ORDER_APPROVAL,"PUBLISHED").map(WorkflowVersionView::from).orElse(null);var draft=versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,PURCHASE_ORDER_APPROVAL,"DRAFT").map(WorkflowVersionView::from).orElse(null);return new WorkflowView(PURCHASE_ORDER_APPROVAL,"Purchase order approval",published,draft,history);}
    @Transactional public WorkflowVersionView createDraft(UUID tenantId,UUID actorId,WorkflowConfig config){if(versions.existsByTenantIdAndWorkflowKeyAndStatus(tenantId,PURCHASE_ORDER_APPROVAL,"DRAFT"))throw conflict("Finish or discard the current draft before creating another");validate(config);var entity=versions.save(new TenantWorkflowVersionEntity(tenantId,PURCHASE_ORDER_APPROVAL,versions.findMaxVersion(tenantId,PURCHASE_ORDER_APPROVAL)+1,toMap(config),actorId));audit.save(new TenantAuditEventEntity(tenantId,actorId,"WORKFLOW_DRAFT_CREATED","workflow",entity.getId(),Map.of("key",PURCHASE_ORDER_APPROVAL,"version",entity.getVersion())));return WorkflowVersionView.from(entity);}
    @Transactional public WorkflowVersionView updateDraft(UUID tenantId,UUID actorId,UUID id,WorkflowConfig config){var entity=versions.findForUpdate(tenantId,id).orElseThrow(()->notFound("Workflow version not found"));if(!entity.getWorkflowKey().equals(PURCHASE_ORDER_APPROVAL))throw notFound("Workflow version not found");validate(config);entity.updateDraft(toMap(config));audit.save(new TenantAuditEventEntity(tenantId,actorId,"WORKFLOW_DRAFT_UPDATED","workflow",id,Map.of("version",entity.getVersion())));return WorkflowVersionView.from(entity);}
    @Transactional(readOnly=true) public ValidationResult validate(UUID tenantId,UUID id){var entity=version(tenantId,id);WorkflowConfig config=fromMap(entity.getConfiguration());validate(config);return new ValidationResult(true,List.of("Transition graph is acyclic and all states are reachable: draft → pending approval → approved/rejected.","Approver role and monetary threshold are valid."),preview(config,new BigDecimal("1000000.00")));}
    @Transactional(readOnly=true) public PreviewResult preview(UUID tenantId,UUID id,BigDecimal amount){if(amount==null||amount.signum()<0)throw badRequest("Preview amount must be zero or greater");return preview(fromMap(version(tenantId,id).getConfiguration()),amount);}
    @Transactional public WorkflowVersionView publish(UUID tenantId,UUID actorId,UUID id){var entity=versions.findForUpdate(tenantId,id).orElseThrow(()->notFound("Workflow version not found"));if(!entity.getWorkflowKey().equals(PURCHASE_ORDER_APPROVAL))throw notFound("Workflow version not found");validate(fromMap(entity.getConfiguration()));versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,PURCHASE_ORDER_APPROVAL,"PUBLISHED").ifPresent(current->current.rollback());entity.publish();audit.save(new TenantAuditEventEntity(tenantId,actorId,"WORKFLOW_PUBLISHED","workflow",id,Map.of("key",PURCHASE_ORDER_APPROVAL,"version",entity.getVersion())));return WorkflowVersionView.from(entity);}
    @Transactional public WorkflowView rollback(UUID tenantId,UUID actorId){var current=versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,PURCHASE_ORDER_APPROVAL,"PUBLISHED").orElseThrow(()->conflict("There is no published workflow to roll back"));var previous=versions.findAllByTenantIdAndWorkflowKeyOrderByVersionDesc(tenantId,PURCHASE_ORDER_APPROVAL).stream().filter(item->item.getVersion()<current.getVersion()&&"ROLLED_BACK".equals(item.getStatus())).findFirst().orElseThrow(()->conflict("There is no earlier published version to restore"));current.rollback();previous.republish();audit.save(new TenantAuditEventEntity(tenantId,actorId,"WORKFLOW_ROLLED_BACK","workflow",previous.getId(),Map.of("fromVersion",current.getVersion(),"toVersion",previous.getVersion())));return view(tenantId);}
    @Transactional(readOnly=true) public Policy activePolicy(UUID tenantId){return versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,PURCHASE_ORDER_APPROVAL,"PUBLISHED").map(entity->policy(fromMap(entity.getConfiguration()),entity.getVersion())).orElse(new Policy(BigDecimal.ZERO,1,"MANAGER",0));}

    private PreviewResult preview(WorkflowConfig config,BigDecimal amount){return new PreviewResult(amount,amount.compareTo(config.amountThreshold())>=0?config.requiredApprovals():1,config.approverRole(),amount.compareTo(config.amountThreshold())>=0);}
    private Policy policy(WorkflowConfig config,int version){return new Policy(config.amountThreshold(),config.requiredApprovals(),config.approverRole(),version);}
    private void validate(WorkflowConfig config){if(config==null||config.amountThreshold()==null||config.amountThreshold().signum()<0||config.amountThreshold().compareTo(new BigDecimal("1000000000000"))>0)throw badRequest("Approval threshold must be between 0 and 1,000,000,000,000");if(config.requiredApprovals()<1||config.requiredApprovals()>3)throw badRequest("Required approvers must be between 1 and 3");if(!Set.of("MANAGER","ADMIN","OWNER").contains(config.approverRole()))throw badRequest("Approver role must be MANAGER, ADMIN, or OWNER");}
    private Map<String,Object> toMap(WorkflowConfig config){return Map.of("amountThreshold",config.amountThreshold(),"requiredApprovals",config.requiredApprovals(),"approverRole",config.approverRole());}
    private WorkflowConfig fromMap(Map<String,Object> config){return new WorkflowConfig(new BigDecimal(String.valueOf(config.get("amountThreshold"))),((Number)config.get("requiredApprovals")).intValue(),String.valueOf(config.get("approverRole")));}
    private TenantWorkflowVersionEntity version(UUID tenantId,UUID id){return versions.findById(id).filter(entity->entity.getTenantId().equals(tenantId)&&entity.getWorkflowKey().equals(PURCHASE_ORDER_APPROVAL)).orElseThrow(()->notFound("Workflow version not found"));}
    private ResponseStatusException badRequest(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private ResponseStatusException conflict(String message){return new ResponseStatusException(HttpStatus.CONFLICT,message);}private ResponseStatusException notFound(String message){return new ResponseStatusException(HttpStatus.NOT_FOUND,message);}
    public record WorkflowConfig(BigDecimal amountThreshold,int requiredApprovals,String approverRole){}
    public record Policy(BigDecimal amountThreshold,int requiredApprovals,String approverRole,int version){}
    public record PreviewResult(BigDecimal amount,int requiredApprovals,String approverRole,boolean thresholdTriggered){}
    public record ValidationResult(boolean valid,List<String> checks,PreviewResult highValuePreview){}
    public record WorkflowVersionView(UUID id,int version,String status,WorkflowConfig configuration,UUID createdBy,java.time.Instant createdAt,java.time.Instant publishedAt){static WorkflowVersionView from(TenantWorkflowVersionEntity entity){Map<String,Object> config=entity.getConfiguration();return new WorkflowVersionView(entity.getId(),entity.getVersion(),entity.getStatus(),new WorkflowConfig(new BigDecimal(String.valueOf(config.get("amountThreshold"))),((Number)config.get("requiredApprovals")).intValue(),String.valueOf(config.get("approverRole"))),entity.getCreatedBy(),entity.getCreatedAt(),entity.getPublishedAt());}}
    public record WorkflowView(String key,String name,WorkflowVersionView published,WorkflowVersionView draft,List<WorkflowVersionView> history){}
}
